import{_ as t,o,c as d,a0 as r}from"./chunks/framework.DoRPXVp_.js";const h=JSON.parse('{"title":"Lattice 代码库整体评审报告（2026-09-17）","description":"","frontmatter":{},"headers":[],"relativePath":"reviews/2026-09-17-codebase-review.md","filePath":"reviews/2026-09-17-codebase-review.md"}'),c={name:"reviews/2026-09-17-codebase-review.md"};function a(n,e,i,s,l,g){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="lattice-代码库整体评审报告-2026-09-17" tabindex="-1">Lattice 代码库整体评审报告（2026-09-17） <a class="header-anchor" href="#lattice-代码库整体评审报告-2026-09-17" aria-label="Permalink to &quot;Lattice 代码库整体评审报告（2026-09-17）&quot;">​</a></h1><ul><li><strong>评审范围</strong>：隧道打通全链路（Signaling → ICE → WireGuard Bind → LRP Relay → Probe 状态机 → netmap 应用）、整体架构、稳定性、性能。</li><li><strong>评审方法</strong>：人工通读核心代码 + 定向抽查。未深读：gVisor 沙箱内部、<code>internal/server/service/ai.go</code>、K8s reconcilers 细节、前端、Windows Bind。</li><li><strong>验证状态</strong>：<code>go build ./...</code> 通过；<code>go test ./internal/relay/... ./internal/server/transport/... ./internal/agent/infra/...</code> 全绿；<code>go vet</code> 在已评审包上无告警。测试文件 99 / 源文件 400。</li><li><strong>行号基准</strong>：<code>new_dev</code> 分支，评审时工作区含 netmap-push 未提交改动（<code>internal/agent/node.go</code>、<code>internal/server/nats/nats.go</code>）。</li></ul><hr><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>设计意图清晰、注释质量罕见——三阶段初始化、状态机防重入、STUN/WG 共享端口解复用都做得有章法。但 <strong>LRP relay 是当前最薄弱的一环</strong>：无鉴权、无帧长度上限、并发写无锁、断线不重连，四个问题叠加意味着&quot;relay 兜底&quot;这条承诺的路径在生产 NAT 环境下既不安全也不可靠。其次是 IPv6 数据面出站路径疑似从代码层面就是坏的。建议在继续堆功能（含 iOS）之前，先集中修 relay 与下列 P1。</p><hr><h2 id="一、隧道打通-连接生命周期" tabindex="-1">一、隧道打通（连接生命周期） <a class="header-anchor" href="#一、隧道打通-连接生命周期" aria-label="Permalink to &quot;一、隧道打通（连接生命周期）&quot;">​</a></h2><p>设计链路：注册 → NATS 信令交换 SYN/ACK（携带 peer info）→ pion/ice 打洞（STUN-only，无 TURN）→ 成功后关闭 ICE agent、将 endpoint 写入 WireGuard，靠 liveness ticker（15s 查握手、45s 判死）+ PersistentKeepalive 维持 → ICE 失败回退 LRP relay（TCP/QUIC）；LRP 先就绪时给 ICE 500ms 加塞窗口，ICE 后到可升级回 P2P。状态机 + epoch + <code>restartInProgress</code> 防重入的骨架是好的。</p><h3 id="已确认问题" tabindex="-1">已确认问题 <a class="header-anchor" href="#已确认问题" aria-label="Permalink to &quot;已确认问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>级别</th><th>问题</th><th>位置</th></tr></thead><tbody><tr><td>1</td><td><strong>P0·安全</strong></td><td>relay 注册零鉴权，服务端直接采信客户端自报 ID，可冒充任意 peer 劫持其 relay 会话（收加密包做流量分析、注入垃圾包、DoS 其 relay 连通性），且无 workspace 隔离；叠加 QUIC 客户端 <code>InsecureSkipVerify: true</code>，MITM 也可接管</td><td><code>internal/relay/lrp_server.go:119</code>、<code>lrp_server_quic.go:116</code>、<code>lrp_client_quic.go:74</code></td></tr><tr><td>2</td><td><strong>P0·安全/稳定</strong></td><td>relay TCP 服务端 <code>PayloadLen</code>（u32）无上限校验，<code>make([]byte, HeaderSize+int(h.PayloadLen))</code> 一个 12 字节恶意头即可触发 ~4GB 分配 → OOM DoS。客户端侧有检查（<code>lrp_client_tcp.go:248,264</code>），服务端漏了</td><td><code>internal/relay/lrp_server.go:151</code></td></tr><tr><td>3</td><td><strong>P0·并发</strong></td><td>relay 转发写无锁：<code>SessionManager.Relay</code> 直接 <code>session.Stream.Write(frame)</code>，TCP 会话的 Stream 是 bufio 包装（非线程安全），两个来源 peer 同时向同一目标转发 → 数据竞争 + 帧交错损坏</td><td><code>internal/relay/session_manager.go:77</code>、<code>conn.go:32-39</code></td></tr><tr><td>4</td><td><strong>P0·稳定</strong></td><td>会话重注册竞态：旧连接 <code>defer Unregister(fromId)</code>，客户端重连时新连接 Register 覆盖 map → 旧连接断开时把<strong>新会话</strong>从 map 删除 → relay 黑洞直到下次重连。QUIC 侧同样</td><td><code>internal/relay/lrp_server.go:125</code>、<code>lrp_server_quic.go:119</code></td></tr><tr><td>5</td><td><strong>P1·稳定</strong></td><td>relay 客户端无任何重连逻辑：只在构造时 Connect 一次，<code>writerLoop</code> 写失败直接 return，无 supervisor；relay 断开后该节点永久失去兜底路径（对比 NATS 客户端 <code>MaxReconnects(-1)</code>）</td><td><code>internal/relay/lrp_client_tcp.go:68,159-198</code>、<code>lrp_client_quic.go:63</code></td></tr><tr><td>6</td><td><strong>P1·需运行时验证</strong></td><td>IPv6 出站路径疑似整体损坏：<code>send6</code> 从不设置目标端口（代码被注释），且 <code>udpAddrPool</code> 缓冲被 <code>send4</code> 重切成 4 字节后 Put 回池，<code>send6</code> 的 copy 只能拷进 4 字节 → v6 地址截断 + 端口为陈旧值/0</td><td><code>internal/agent/infra/conn.go:388,426-427</code></td></tr><tr><td>7</td><td><strong>P1·性能</strong></td><td>信令回调里做重 OS 操作且持有 dialer 锁：<code>onPeerReceived</code> 在 <code>i.mu</code> 双检锁内直通 <code>RegisterPeer</code>/<code>ApplyRoute</code>（iptables/路由 exec）；NATS 订阅回调串行分发，一次慢路由操作卡住该节点所有 peer 的信令</td><td><code>internal/server/transport/ice_dialer.go:190-200</code></td></tr><tr><td>8</td><td><strong>P2·资源</strong></td><td>ICE 先赢时 LRP 传输泄漏：<code>discover()</code> 中 ICE 先返回即 return，仍在拨号的 LRP 传输进缓冲 channel 后无人 Close，relay 会话挂到进程重启</td><td><code>internal/server/transport/probe.go:345-399</code></td></tr><tr><td>9</td><td><strong>P2·稳定</strong></td><td>liveness ticker 被瞬时错误永久杀死：<code>getHandshake</code> 返回一次错误即退出整个监控循环，之后该 peer 静默死亡不再被检测。应 continue 而非 return</td><td><code>internal/server/transport/probe.go:156-163</code></td></tr><tr><td>10</td><td><strong>P2</strong></td><td><code>iceDialer.Close</code> 不取消 SYN ticker（只有收到 ACK 才 cancel），每个 dialer 关闭后 goroutine 空转至多 60s；lrpDialer 的 Close 是对称正确的</td><td><code>ice_dialer.go:157</code> vs <code>lrp_dialer.go:301-312</code></td></tr><tr><td>11</td><td><strong>P3</strong></td><td>ICE 接口过滤启发式太脆：只排除 <code>docker/veth/br-/wf*</code> 前缀，macOS 其他 VPN 的 <code>utun*</code>、<code>tailscale0</code> 会成为候选；<code>wf</code> 前缀也会误伤</td><td><code>ice_dialer.go:554-558</code></td></tr></tbody></table><h3 id="ttfh-视角的行为-值得知晓而非缺陷" tabindex="-1">TTFH 视角的行为（值得知晓而非缺陷） <a class="header-anchor" href="#ttfh-视角的行为-值得知晓而非缺陷" aria-label="Permalink to &quot;TTFH 视角的行为（值得知晓而非缺陷）&quot;">​</a></h3><p>对端离线时，一轮发现 = 65s Dial 超时（<code>ice_dialer.go:464</code>）+ 10s 退避（<code>probe.go:326-328</code>），约 140s 后 probe 进入 <code>StateClosed</code> 静默；对端重新上线靠 RESTART_NOTIFY / netmap 版本变更收敛。配合 netmap-changed 推送（见第六节），该路径收敛会显著加快。</p><hr><h2 id="二、稳定性" tabindex="-1">二、稳定性 <a class="header-anchor" href="#二、稳定性" aria-label="Permalink to &quot;二、稳定性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>级别</th><th>问题</th><th>位置</th></tr></thead><tbody><tr><td>12</td><td><strong>P1·并发</strong></td><td>netmap 应用无串行化：<code>ApplyFullConfig</code> 有 5 个并发入口（Start、NATS MESSAGE push、<code>RunNetmapSync</code> 轮询、NATS reconnect handler、netmap-changed 回调）；<code>MessageHandler</code> 无锁，<code>Provisioner.mu</code> 标注 <code>nolint:unused</code>，<code>SetConfig</code> 的 IpcGet→比较→IpcSet 是裸 check-then-act</td><td><code>internal/agent/message_handler.go:127</code>、<code>provision/provisioner.go:182</code>、<code>node.go:587-596,629-643</code></td></tr><tr><td>13</td><td><strong>P2</strong></td><td>NATS reconnect handler 写 <code>node.current = peer</code> 与 <code>StatusSnapshot</code> 读无锁竞争</td><td><code>node.go:518</code> vs <code>node.go:677</code></td></tr><tr><td>14</td><td><strong>P3</strong></td><td>DB 默认写进程 CWD（<code>lattice.db</code>），状态位置取决于启动目录（仓库根已出现 <code>-shm/-wal/.bak</code>）</td><td><code>internal/db/db.go:59</code></td></tr><tr><td>15</td><td><strong>P3</strong></td><td>agent 启动创建 JetStream 流 &quot;LATTICE&quot;（subjects <code>signals.&gt;</code>），实际信令 subject 是 <code>lattice.signals.peers.*</code> 不匹配——纯死重，还有多 agent 并发创建竞态</td><td><code>internal/server/nats/nats.go:127-142</code></td></tr><tr><td>16</td><td><strong>P3</strong></td><td>信令/通知 subject 直接拼接 appID，含 <code>.</code> <code>*</code> <code>&gt;</code> 或空格即可注入/错投，未见字符校验</td><td><code>internal/agent/infra/notify.go:24</code></td></tr><tr><td>17</td><td><strong>P3</strong></td><td><code>blackhole4/6</code> 死代码（只在 Close 置 false）；<code>FilteringUDPMux.DroppedCount()</code> 无任何调用方——过载丢包不可观测</td><td><code>conn.go:73-74</code>、<code>mux_filter.go:139</code></td></tr></tbody></table><p>测试面：核心路径（probe 状态机、relay 协议、notify）有针对性用例且当前全绿；但 relay 的鉴权缺失/长度上限/并发写恰好都在测试盲区。</p><hr><h2 id="三、性能" tabindex="-1">三、性能 <a class="header-anchor" href="#三、性能" aria-label="Permalink to &quot;三、性能&quot;">​</a></h2><ul><li><strong>数据面 inbound</strong>：单 goroutine readLoop（单核）→ 每包一次分配 + copy → 512 深度 channel（满则丢、无指标）→ Bind 再 copy（<code>mux_filter.go:108-143</code>、<code>conn.go:264-276</code>）。百兆级没问题，Gbps 级是瓶颈；outbound 在 Linux 已用 WriteBatch。短期先补 droppedCount 指标，长期批量化。</li><li><strong>relay TCP 转发</strong>：每帧新分配 + <code>ReadWriterConn.Write</code> 每帧强制 Flush；已有 sync.Pool（<code>pool.go</code>）但只用在客户端 header。</li><li><strong>控制面</strong>：<code>notifyWorkspacePeers</code> 每次注册向全 workspace 逐个 publish（<code>peer.go:383-399</code>），配合客户端刷新逻辑，大 workspace 连续 join 会造成 N×全量刷新风暴——建议服务端去抖（合并 1-2s）+ 客户端合并刷新。</li><li><strong>基准</strong>：<code>hack/bench/</code>（TTFH/吞吐/API p99 + Shields 徽章）方法论成型，SLA gate 按计划推迟到 4 周基线，决策合理。</li></ul><hr><h2 id="四、架构" tabindex="-1">四、架构 <a class="header-anchor" href="#四、架构" aria-label="Permalink to &quot;四、架构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>级别</th><th>问题</th></tr></thead><tbody><tr><td>18</td><td><strong>P1·架构</strong></td><td><code>internal/agent</code> 与 <code>internal/server</code> <strong>双向 import</strong>，边界名存实亡：agent 侧 import <code>server/client</code>、<code>server/nats</code>、<code>server/transport</code>（<code>node.go:34-36</code>）；server 侧 20+ 文件 import <code>agent/infra/config/log</code>，<code>server/run.go</code> 直接 import agent 包。数据面核心（Probe/ICE/LRP dialer）住在 <code>server/transport</code> 却被 agent 当运行时用。建议把共享运行时抽成 <code>internal/dataplane</code>（或 pkg/），<code>server/</code> 收敛为纯控制面</td></tr><tr><td>19</td><td><strong>P2</strong></td><td>巨型文件：<code>server/service/ai.go</code> 1868 行、<code>agent/controller/peer_controller.go</code> 1075 行、<code>server/service/peer.go</code> 1059 行——服务层上帝对象</td></tr><tr><td>20</td><td><strong>P2</strong></td><td>Pro 门控（build tags，7 文件 + <code>requireFeature</code> 402 中间件）可用，建议把 community/pro 交叉点收敛到统一 capability 注册处</td></tr><tr><td>21</td><td><strong>P3</strong></td><td>All-in-one（内嵌 NATS + SQLite + gVisor + wireguard-go 同进程）部署体验好，但各组件内存水位无上限配置，大 workspace 下的隔离性需文档化</td></tr></tbody></table><hr><h2 id="五、设计亮点-值得保持" tabindex="-1">五、设计亮点（值得保持） <a class="header-anchor" href="#五、设计亮点-值得保持" aria-label="Permalink to &quot;五、设计亮点（值得保持）&quot;">​</a></h2><ol><li><code>NewNode</code> 三阶段初始化把每个竞态窗口的消除理由写成注释（<code>node.go:184-207, 417-421</code>），是教科书级的&quot;为什么是这个顺序&quot;文档。</li><li><code>FilteringUDPMux</code> 单读者解复用（STUN→ICE / 非 STUN→WG）干净消除共享端口读取竞争，v6 对称处理。</li><li>Probe 状态机 + epoch + <code>restartInProgress</code> 防重入，LRP→ICE 升级路径明确标注 &quot;P1 bug fix&quot;（<code>probe_factory.go:329-341</code>），踩坑被系统性吸收。</li><li>推送 + 轮询 + reconnect 三通道收敛的 netmap 设计，鲁棒性思路正确。</li></ol><hr><h2 id="六、netmap-push-未提交改动评审意见-2026-09-16-改动" tabindex="-1">六、netmap push 未提交改动评审意见（2026-09-16 改动） <a class="header-anchor" href="#六、netmap-push-未提交改动评审意见-2026-09-16-改动" aria-label="Permalink to &quot;六、netmap push 未提交改动评审意见（2026-09-16 改动）&quot;">​</a></h2><p>方向正确、闭环完整（服务端 <code>peer.go:395,417</code> 发布 → agent <code>node.go:491</code> 订阅刷新）。建议：</p><ol><li><code>SubscribeRaw</code> 回调目前在 NATS 分发 goroutine 里同步跑最长 10s 的 HTTP+全量应用——通知风暴时会排队积压。改成丢 worker goroutine + 250ms 去抖 + 原子标志防重入。</li><li>服务端目前只接了注册/更新两个点，policy/route/relay 变更路径尚未发布通知，push 与 30s 轮询并存期行为不一致是暂态——在 <code>docs/superpowers/plans/2026-09-16-netmap-push-and-endpoint-ui.md</code> 里列清剩余接入点。</li><li>agent 侧 <code>RefreshConfig</code> 每次全量应用，可像 <code>RunNetmapSync</code> 一样先比 <code>ConfigVersion</code> 再应用。</li><li>补 push→refresh 的 agent 侧单测（publish 侧已有 <code>notify_test.go</code>）。</li></ol><hr><h2 id="七、优先级行动清单" tabindex="-1">七、优先级行动清单 <a class="header-anchor" href="#七、优先级行动清单" aria-label="Permalink to &quot;七、优先级行动清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>事项</th></tr></thead><tbody><tr><td>P0</td><td>relay 三件套：Register 鉴权（token/签名）、PayloadLen 上限、Session 写锁</td></tr><tr><td>P0</td><td>relay 重注册 Unregister 竞态（按会话身份删除）</td></tr><tr><td>P1</td><td>relay 客户端自动重连（对齐 NATS <code>MaxReconnects(-1)</code> 姿势）</td></tr><tr><td>P1</td><td>验证/修复 <code>send6</code> IPv6 出站路径</td></tr><tr><td>P1</td><td>netmap 应用串行化 + netmap-changed 回调去抖</td></tr><tr><td>P2</td><td>信令路径 OS 操作移出锁外、LRP 泄漏关闭、liveness 容忍瞬时错误、droppedCount 暴露为指标</td></tr><tr><td>P2+</td><td>架构：抽 <code>internal/dataplane</code>，拆 <code>ai.go</code> / <code>peer_controller.go</code> 巨型文件</td></tr></tbody></table>',32)])])}const u=t(c,[["render",a]]);export{h as __pageData,u as default};
